// Client for the ledgerbook program, generated by TypeSOL from its IDL. Do not edit: `typesol build` (or `typesol client`) rewrites it.
import {
  AccountRole,
  type Address,
  type Codec,
  type FetchAccountConfig,
  type GetAccountInfoApi,
  type Instruction,
  type ProgramDerivedAddress,
  type ReadonlyUint8Array,
  type Rpc,
  SOLANA_ERROR__INSTRUCTION_ERROR__CUSTOM,
  type TransactionSigner,
  addCodecSizePrefix,
  address,
  createCodec,
  fetchEncodedAccount,
  fixCodecSize,
  getAddressCodec,
  getAddressEncoder,
  getArrayCodec,
  getBase64Encoder,
  getBooleanCodec,
  getBytesCodec,
  getNullableCodec,
  getProgramDerivedAddress,
  getStructCodec,
  getU32Codec,
  getU64Codec,
  getU8Codec,
  getUtf8Codec,
  getUtf8Decoder,
  getUtf8Encoder,
  isSolanaError,
  transformCodec,
} from "@solana/kit";

export const PROGRAM_ADDRESS = address("11111111111111111111111111111112");

// ---- Helpers ----
const concat = (parts: ReadonlyUint8Array[]): Uint8Array => {
  const out = new Uint8Array(parts.reduce((n, p) => n + p.length, 0));
  let at = 0;
  for (const p of parts) out.set(p, (at += p.length) - p.length);
  return out;
};
const hasPrefix = (data: ReadonlyUint8Array, prefix: ReadonlyUint8Array) => data.length >= prefix.length && prefix.every((b, i) => data[i] === b);
const isSigner = (v: TransactionSigner | Address): v is TransactionSigner => typeof v === "object" && v !== null && "address" in v;
const key = (v: TransactionSigner | Address | undefined | null): Address => {
  if (v === undefined || v === null) throw new Error("a seed account is missing");
  return isSigner(v) ? v.address : v;
};
const required = <T>(v: T | undefined, name: string): T => {
  if (v === undefined) throw new Error("account " + name + " is required");
  return v;
};
const meta = (v: TransactionSigner | Address, role: AccountRole) => (isSigner(v) ? { address: v.address, role, signer: v } : { address: v, role });
/** TypeSOL FixedString<N> in account data: u32 length, then N bytes (UTF-8, zero-padded). */
const fixedString = (cap: number): Codec<string, string> =>
  transformCodec(
    getStructCodec([["len", getU32Codec()], ["bytes", fixCodecSize(getBytesCodec(), cap)]]),
    (s: string) => {
      const b = getUtf8Encoder().encode(s);
      if (b.length > cap) throw new Error("string is " + b.length + " bytes; the field holds " + cap);
      const padded = new Uint8Array(cap);
      padded.set(b);
      return { len: b.length, bytes: padded };
    },
    (v) => getUtf8Decoder().decode(v.bytes.slice(0, Math.min(v.len, cap))),
  );
/** An Option of fixed size: a tag, then the value (all zero when empty). TypeSOL account data uses a u8 tag, COption a u32. */
const fixedOption = <From, To extends From>(inner: Codec<From, To>, size: number, tag: Codec<number, number>, tagSize: number): Codec<From | null, To | null> =>
  createCodec<From | null, To | null>({
    fixedSize: tagSize + size,
    write: (value, bytes, offset) => {
      bytes.fill(0, offset, offset + tagSize + size);
      tag.write(value === null ? 0 : 1, bytes, offset);
      if (value !== null) inner.write(value, bytes, offset + tagSize);
      return offset + tagSize + size;
    },
    read: (bytes, offset) => [tag.read(bytes, offset)[0] ? inner.read(bytes, offset + tagSize)[0] : null, offset + tagSize + size],
  });
/** A unit enum: its variant index as a u8, checked against the number of variants. */
const unitEnum = <T extends number>(count: number): Codec<T, T> =>
  transformCodec(getU8Codec(), (v: T) => v, (n) => {
    if (n >= count) throw new Error("enum variant " + n + " is out of range");
    return n as T;
  }) as unknown as Codec<T, T>;

// ---- Types ----
export interface Entry {
  who: Address;
  amount: bigint;
  status: Status;
  note: string;
}
export interface EntryArgs {
  who: Address;
  amount: number | bigint;
  status: Status;
  note: string;
}
export function getEntryCodec(): Codec<EntryArgs, Entry> {
  return getStructCodec([["who", getAddressCodec()], ["amount", getU64Codec()], ["status", getStatusCodec()], ["note", fixedString(16)]]) as unknown as Codec<EntryArgs, Entry>;
}

export interface Book {
  admin: Address;
  title: string;
  approver: Address | null;
  lastAmount: bigint | null;
  /** Must be last: the account grows by one Entry per push. */
  entries: Array<Entry>;
}
export interface BookArgs {
  admin: Address;
  title: string;
  approver: Address | null;
  lastAmount: number | bigint | null;
  entries: Array<EntryArgs>;
}
export function getBookCodec(): Codec<BookArgs, Book> {
  return getStructCodec([["admin", getAddressCodec()], ["title", fixedString(24)], ["approver", fixedOption(getAddressCodec(), 32, getU8Codec(), 1)], ["lastAmount", fixedOption(getU64Codec(), 8, getU8Codec(), 1)], ["entries", getArrayCodec(getEntryCodec())]]) as unknown as Codec<BookArgs, Book>;
}

export interface Filed {
  index: bigint;
  who: Address;
  amount: bigint;
  memo: bigint | null;
}
export interface FiledArgs {
  index: number | bigint;
  who: Address;
  amount: number | bigint;
  memo: number | bigint | null;
}
export function getFiledCodec(): Codec<FiledArgs, Filed> {
  return getStructCodec([["index", getU64Codec()], ["who", getAddressCodec()], ["amount", getU64Codec()], ["memo", getNullableCodec(getU64Codec())]]) as unknown as Codec<FiledArgs, Filed>;
}

export const Status = { Pending: 0, Approved: 1, Rejected: 2 } as const;
export type Status = (typeof Status)[keyof typeof Status];
export type StatusArgs = Status;
export function getStatusCodec(): Codec<StatusArgs, Status> {
  return unitEnum<Status>(3);
}

// ---- Accounts ----
const BookAccount_DISCRIMINATOR = new Uint8Array([121, 34, 121, 35, 91, 62, 85, 222]);
/** Book account data: the 8-byte discriminator, then the fields. */
const BookAccount = {
  discriminator: BookAccount_DISCRIMINATOR,
  decode(data: ReadonlyUint8Array): Book {
    if (!hasPrefix(data, BookAccount_DISCRIMINATOR)) throw new Error("not a Book account (discriminator mismatch)");
    return getBookCodec().decode(data, 8);
  },
  encode(value: BookArgs): ReadonlyUint8Array {
    return concat([BookAccount_DISCRIMINATOR, getBookCodec().encode(value)]);
  },
  async fetch(rpc: Rpc<GetAccountInfoApi>, at: Address, config?: FetchAccountConfig): Promise<Book> {
    const found = await fetchEncodedAccount(rpc, at, config);
    if (!found.exists) throw new Error("Book account does not exist: " + at);
    return BookAccount.decode(found.data);
  },
  async fetchMaybe(rpc: Rpc<GetAccountInfoApi>, at: Address, config?: FetchAccountConfig): Promise<Book | null> {
    const found = await fetchEncodedAccount(rpc, at, config);
    return found.exists ? BookAccount.decode(found.data) : null;
  },
};

// ---- Instructions ----
export interface CreateAccounts {
  admin: TransactionSigner | Address;
  book?: Address;
  systemProgram?: Address;
}
export interface CreateArgs {
  title: string;
  approver: Address | null;
}
async function buildCreate(input: CreateAccounts, args: CreateArgs): Promise<Instruction> {
  const $admin = input.admin;
  const $systemProgram = input.systemProgram ?? address("11111111111111111111111111111111");
  const $book = input.book ?? (await getProgramDerivedAddress({ programAddress: PROGRAM_ADDRESS, seeds: [new Uint8Array([98, 111, 111, 107]), getAddressEncoder().encode(key($admin)), getUtf8Encoder().encode(args.title)] }))[0];
  return {
    programAddress: PROGRAM_ADDRESS,
    accounts: [
      meta(required($admin, "admin"), AccountRole.WRITABLE_SIGNER),
      meta($book, AccountRole.WRITABLE),
      meta($systemProgram, AccountRole.READONLY),
    ],
    data: concat([new Uint8Array([24, 30, 200, 40, 5, 28, 7, 119]), getStructCodec([["title", addCodecSizePrefix(getUtf8Codec(), getU32Codec())], ["approver", getNullableCodec(getAddressCodec())]]).encode(args)]),
  } as Instruction;
}

export interface FileAccounts {
  who: TransactionSigner | Address;
  book: Address;
  systemProgram?: Address;
}
export interface FileArgs {
  amount: number | bigint;
  note: string;
  memo: number | bigint | null;
}
async function buildFile(input: FileAccounts, args: FileArgs): Promise<Instruction> {
  const $who = input.who;
  const $book = input.book;
  const $systemProgram = input.systemProgram ?? address("11111111111111111111111111111111");
  return {
    programAddress: PROGRAM_ADDRESS,
    accounts: [
      meta(required($who, "who"), AccountRole.WRITABLE_SIGNER),
      meta(required($book, "book"), AccountRole.WRITABLE),
      meta($systemProgram, AccountRole.READONLY),
    ],
    data: concat([new Uint8Array([18, 110, 74, 240, 115, 244, 183, 209]), getStructCodec([["amount", getU64Codec()], ["note", addCodecSizePrefix(getUtf8Codec(), getU32Codec())], ["memo", getNullableCodec(getU64Codec())]]).encode(args)]),
  } as Instruction;
}

export interface DecideAccounts {
  approver: TransactionSigner | Address;
  book: Address;
}
export interface DecideArgs {
  index: number | bigint;
  approve: boolean;
}
async function buildDecide(input: DecideAccounts, args: DecideArgs): Promise<Instruction> {
  const $approver = input.approver;
  const $book = input.book;
  return {
    programAddress: PROGRAM_ADDRESS,
    accounts: [
      meta(required($approver, "approver"), AccountRole.READONLY_SIGNER),
      meta(required($book, "book"), AccountRole.WRITABLE),
    ],
    data: concat([new Uint8Array([123, 125, 184, 125, 249, 43, 113, 15]), getStructCodec([["index", getU64Codec()], ["approve", getBooleanCodec()]]).encode(args)]),
  } as Instruction;
}

export interface ApproveManyAccounts {
  approver: TransactionSigner | Address;
  book: Address;
}
export interface ApproveManyArgs {
  indices: Array<number | bigint>;
}
/** Approve many entries at once from a Vec<u64> argument. */
async function buildApproveMany(input: ApproveManyAccounts, args: ApproveManyArgs): Promise<Instruction> {
  const $approver = input.approver;
  const $book = input.book;
  return {
    programAddress: PROGRAM_ADDRESS,
    accounts: [
      meta(required($approver, "approver"), AccountRole.READONLY_SIGNER),
      meta(required($book, "book"), AccountRole.WRITABLE),
    ],
    data: concat([new Uint8Array([91, 62, 156, 120, 217, 247, 3, 155]), getStructCodec([["indices", getArrayCodec(getU64Codec())]]).encode(args)]),
  } as Instruction;
}

export interface SetApproverAccounts {
  admin: TransactionSigner | Address;
  book: Address;
}
export interface SetApproverArgs {
  approver: Address | null;
}
async function buildSetApprover(input: SetApproverAccounts, args: SetApproverArgs): Promise<Instruction> {
  const $admin = input.admin;
  const $book = input.book;
  return {
    programAddress: PROGRAM_ADDRESS,
    accounts: [
      meta(required($admin, "admin"), AccountRole.READONLY_SIGNER),
      meta(required($book, "book"), AccountRole.WRITABLE),
    ],
    data: concat([new Uint8Array([139, 202, 200, 122, 109, 173, 219, 116]), getStructCodec([["approver", getNullableCodec(getAddressCodec())]]).encode(args)]),
  } as Instruction;
}

export interface ResetAccounts {
  admin: TransactionSigner | Address;
  book: Address;
}
/** Shrinks the account back to its fixed part. */
async function buildReset(input: ResetAccounts): Promise<Instruction> {
  const $admin = input.admin;
  const $book = input.book;
  return {
    programAddress: PROGRAM_ADDRESS,
    accounts: [
      meta(required($admin, "admin"), AccountRole.READONLY_SIGNER),
      meta(required($book, "book"), AccountRole.WRITABLE),
    ],
    data: new Uint8Array([23, 81, 251, 84, 138, 183, 240, 214]),
  } as Instruction;
}

export interface TotalAccounts {
  book: Address;
}
export interface TotalArgs {
  status: Status;
}
async function buildTotal(input: TotalAccounts, args: TotalArgs): Promise<Instruction> {
  const $book = input.book;
  return {
    programAddress: PROGRAM_ADDRESS,
    accounts: [
      meta(required($book, "book"), AccountRole.READONLY),
    ],
    data: concat([new Uint8Array([136, 16, 234, 122, 170, 199, 84, 169]), getStructCodec([["status", getStatusCodec()]]).encode(args)]),
  } as Instruction;
}

